# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# X- and XL-form VLE instructions (VLEPEM Rev. 0 Chapter 3; EREF X and XL
# forms).

# CHECK: e_cmph 0, 3, 4 # encoding: [0x7c,0x03,0x20,0x1c]
e_cmph 0, 3, 4
# CHECK: e_cmph 1, 3, 4 # encoding: [0x7c,0x83,0x20,0x1c]
e_cmph 1, 3, 4
# CHECK: e_cmphl 3, 3, 4 # encoding: [0x7d,0x83,0x20,0x5c]
e_cmphl 3, 3, 4
# CHECK: e_mcrf 0, 1 # encoding: [0x7c,0x04,0x00,0x20]
e_mcrf 0, 1
# CHECK: e_mcrf 7, 0 # encoding: [0x7f,0x80,0x00,0x20]
e_mcrf 7, 0
# CHECK: e_crand 0, 1, 2 # encoding: [0x7c,0x01,0x12,0x02]
e_crand 0, 1, 2
# CHECK: e_crandc 0, 1, 2 # encoding: [0x7c,0x01,0x11,0x02]
e_crandc 0, 1, 2
# CHECK: e_creqv 0, 1, 2 # encoding: [0x7c,0x01,0x12,0x42]
e_creqv 0, 1, 2
# CHECK: e_crnand 0, 1, 2 # encoding: [0x7c,0x01,0x11,0xc2]
e_crnand 0, 1, 2
# CHECK: e_crnor 0, 1, 2 # encoding: [0x7c,0x01,0x10,0x42]
e_crnor 0, 1, 2
# CHECK: e_cror 0, 1, 2 # encoding: [0x7c,0x01,0x13,0x82]
e_cror 0, 1, 2
# CHECK: e_crorc 0, 1, 2 # encoding: [0x7c,0x01,0x13,0x42]
e_crorc 0, 1, 2
# CHECK: e_crxor 0, 1, 2 # encoding: [0x7c,0x01,0x11,0x82]
e_crxor 0, 1, 2
# CHECK: e_rlw 3, 4, 5 # encoding: [0x7c,0x83,0x2a,0x30]
e_rlw 3, 4, 5
# CHECK: e_rlw. 3, 4, 5 # encoding: [0x7c,0x83,0x2a,0x31]
e_rlw. 3, 4, 5
# CHECK: e_rlwi 3, 4, 1 # encoding: [0x7c,0x83,0x0a,0x70]
e_rlwi 3, 4, 1
# CHECK: e_rlwi. 3, 4, 1 # encoding: [0x7c,0x83,0x0a,0x71]
e_rlwi. 3, 4, 1
# CHECK: e_slwi 3, 4, 1 # encoding: [0x7c,0x83,0x08,0x70]
e_slwi 3, 4, 1
# CHECK: e_slwi. 3, 4, 1 # encoding: [0x7c,0x83,0x08,0x71]
e_slwi. 3, 4, 1
# CHECK: e_srwi 3, 4, 1 # encoding: [0x7c,0x83,0x0c,0x70]
e_srwi 3, 4, 1
# CHECK: e_srwi. 3, 4, 1 # encoding: [0x7c,0x83,0x0c,0x71]
e_srwi. 3, 4, 1
